package edu.ankara.audiometer.ui.view;
import edu.ankara.audiometer.domain.model.*;import javafx.scene.chart.*;import javafx.scene.control.*;
public final class AudiogramChartPane extends TitledPane { private final LineChart<Number,Number> chart; public AudiogramChartPane(){ NumberAxis x=new NumberAxis(125,9000,1000); x.setLabel("Frequency (Hz)"); NumberAxis y=new NumberAxis(120,-10,-10); y.setLabel("dB HL (lower values higher)"); chart=new LineChart<>(x,y); chart.setTitle("Real-Time Audiogram (Right red O, Left blue X)"); chart.setLegendVisible(true); chart.setCreateSymbols(true); setText("Audiogram Chart"); setCollapsible(false); setContent(chart); } public void update(Audiogram a){ chart.getData().clear(); addSeries("RIGHT red O", Ear.RIGHT, a); addSeries("LEFT blue X", Ear.LEFT, a); } private void addSeries(String name,Ear e,Audiogram a){ XYChart.Series<Number,Number> s=new XYChart.Series<>(); s.setName(name); a.points().stream().filter(p->p.ear()==e).sorted(java.util.Comparator.comparing(p->p.frequency().value())).forEach(p->s.getData().add(new XYChart.Data<>(p.frequency().value(),p.thresholdDbHL().value()))); chart.getData().add(s); } }
